mapper.select:
select hcli.project_id, hcli.project_lease_item_id, hcli.asset_name, hcli.quantity, hcli.price, (hcli.quantity * hcli.price) as total_price, hcli.LEASE_ITEM_ID, hcli.PROJECT_TYPE, (select hli.FULL_NAME from hls_lease_item hli where hli.LEASE_ITEM_ID=hcli.LEASE_ITEM_ID and rownum=1) LEASE_ITEM_ID_N from prj_project_lease_item hcli
hcli.project_id = #{projectId}
and hcli.project_type=#{projectType}

select hcli.project_id, hcli.project_lease_item_id, hcli.asset_name, hcli.quantity, hcli.price, (hcli.quantity * hcli.price) as total_price, hcli.LEASE_ITEM_ID, hcli.PROJECT_TYPE, (select hli.FULL_NAME from hls_lease_item hli where hli.LEASE_ITEM_ID=hcli.LEASE_ITEM_ID and rownum=1) LEASE_ITEM_ID_N from prj_project_lease_item hcli
hcli.project_id = (select pp1.project_id from change_req_info cri1, prj_project pp1 where cri1.change_req_id = pp1.CHANGE_REQ_ID and pp1.data_type in ('CHANGE_REQ_HISTORY', 'HISTORY') and cri1.change_req_id = #{changeReqId} and rownum = 1)
and hcli.project_type=#{projectType}

select hcli.project_id, hcli.project_lease_item_id, hcli.asset_name, hcli.quantity, hcli.price, (hcli.quantity * hcli.price) as total_price, hcli.LEASE_ITEM_ID, hcli.PROJECT_TYPE, (select hli.FULL_NAME from hls_lease_item hli where hli.LEASE_ITEM_ID=hcli.LEASE_ITEM_ID and rownum=1) LEASE_ITEM_ID_N from prj_project_lease_item hcli
hcli.project_id = (select pp1.project_id from change_req_info cri1, prj_project pp1 where cri1.change_req_id = pp1.CHANGE_REQ_ID and pp1.data_type in ('CHANGE_REQ_HISTORY', 'HISTORY') and cri1.change_req_id = #{changeReqId} and rownum = 1)
and hcli.project_type=#{projectType}

select pli.*, c.contract_id, (select approval_number from prj_project where project_id = pli.project_id) approval_number, (select approval_number from prj_project where project_id = pli.project_id) value_name from prj_project_lease_item pli,con_contract c where pli.project_id = c.project_id and pli.ITEM_TYPE='PLANE'
and c.contract_id in
#{item}

SELECT pp.project_id , pp.PROJECT_LEASE_ITEM_ID, hli.LEASE_ITEM_ID, hli.LEASE_ITEM_CODE, hli.LEASE_ITEM_CODE LEASE_ITEM_ID_N, hli.FULL_NAME, hli.FULL_NAME as FULL_NAME_N, hli.lease_item_type, (select hbt.description from hls_business_type hbt where hbt.document_category= 'ASSET_TYPES' and hbt.business_type = hli.asset_types) asset_types_n, (select hdt.description from hls_document_type hdt where hdt.document_category = 'ASSET_TYPES' and hdt.business_type = hli.asset_types and hdt.document_type = hli.asset_types_sub) asset_types_sub_n, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'CHS.CURRENCY_TYPE' and scv.value = hli.currency) currency_n, (SELECT nvl(sum(hlid.net_asset_value), 0) FROM hls_lease_item_detail hlid where hlid.lease_item_id = hli.lease_item_id) as net_asset_value_total, (select h.excel_id from hls_web_excel h where h.enabled_flag = 'Y' and h.excel_type = 'LEASE_RENTAL_REPORT') as excel_id,
(SELECT max(hr.result_id) FROM hls_web_excel_calc_result hr, hls_web_excel hwe where hr.source_document_id = hli.lease_item_id and hwe.excel_id = hr.excel_id and hr.source_document_category = 'HLS_LEASE_ITEM_RENTAL') as result_id
FROM hls_lease_item hli,prj_project_lease_item pp
hli.lease_item_id = pp.lease_item_id and hli.lease_item_type = 'LEASE'
and pp.project_id = #{projectId}
and pp.item_type = #{itemType}

SELECT pp.project_id , pp.PROJECT_LEASE_ITEM_ID, hli.LEASE_ITEM_ID, hli.LEASE_ITEM_CODE, hli.LEASE_ITEM_CODE LEASE_ITEM_ID_N, hli.FULL_NAME, hli.FULL_NAME as FULL_NAME_N, hli.lease_item_type, (select hbt.description from hls_business_type hbt where hbt.document_category= 'ASSET_TYPES' and hbt.business_type = hli.asset_types) asset_types_n, (select hdt.description from hls_document_type hdt where hdt.document_category = 'ASSET_TYPES' and hdt.business_type = hli.asset_types and hdt.document_type = hli.asset_types_sub) asset_types_sub_n, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'CHS.CURRENCY_TYPE' and scv.value = hli.currency) currency_n, (SELECT nvl(sum(hlid.net_asset_value), 0) FROM hls_lease_item_detail hlid where hlid.lease_item_id = hli.lease_item_id) as net_asset_value_total, (select h.excel_id from hls_web_excel h where h.enabled_flag = 'Y' and h.excel_type = 'LEASE_RENTAL_REPORT') as excel_id,
(SELECT max(hr.result_id) FROM hls_web_excel_calc_result hr, hls_web_excel hwe where hr.source_document_id = hli.lease_item_id and hwe.excel_id = hr.excel_id and hr.source_document_category = 'HLS_LEASE_ITEM_RENTAL') as result_id
FROM hls_lease_item hli,prj_project_lease_item pp
hli.lease_item_id = pp.lease_item_id and hli.lease_item_type = 'LEASE'
and pp.project_id = #{projectId}
and pp.item_type = #{itemType}
